const QUESTIONS = [{"id": "a1", "section": "A", "title": "Soalan 1", "intro": "Tukarkan 3/4 juta kepada nombor bulat.", "fields": [{"id": "a1", "type": "math", "kind": "number", "label": "Jawapan akhir", "answer": 750000, "max": 2, "topic": "Nombor bulat dan operasi asas", "model": "3/4 × 1 000 000 = 750 000. Kaedah penukaran betul (1), jawapan 750 000 (1).", "displayUnit": "nombor bulat"}], "topic": "Nombor bulat dan operasi asas"}, {"id": "a2", "section": "A", "title": "Soalan 2", "intro": "Cari nilai anu dalam ayat matematik: (4 800 000 − □) ÷ 4 = 1 100 000.", "fields": [{"id": "a2", "type": "math", "kind": "number", "label": "Jawapan akhir", "answer": 400000, "max": 2, "topic": "Nombor bulat dan operasi asas", "model": "1 100 000 × 4 = 4 400 000 (1). Anu = 4 800 000 − 4 400 000 = 400 000 (1).", "displayUnit": "nombor bulat"}], "topic": "Nombor bulat dan operasi asas"}, {"id": "a3", "section": "A", "title": "Soalan 3", "intro": "Hitung 2 1/4 ÷ 3/4.", "fields": [{"id": "a3", "type": "math", "kind": "number", "label": "Jawapan akhir", "answer": 3, "max": 2, "topic": "Pecahan, perpuluhan dan peratus", "model": "2 1/4 ÷ 3/4 = 9/4 × 4/3 (1) = 3 (1)."}], "topic": "Pecahan, perpuluhan dan peratus"}, {"id": "a4", "section": "A", "title": "Soalan 4", "intro": "Hitung 6.72 ÷ 0.8.", "fields": [{"id": "a4", "type": "math", "kind": "number", "label": "Jawapan akhir", "answer": 8.4, "max": 2, "topic": "Pecahan, perpuluhan dan peratus", "model": "6.72 ÷ 0.8 = 67.2 ÷ 8 (1) = 8.4 (1)."}], "topic": "Pecahan, perpuluhan dan peratus"}, {"id": "a5", "section": "A", "title": "Soalan 5", "intro": "Harga tanda sebuah beg ialah RM240. Diskaun 15% diberikan. Berapakah harga beg selepas diskaun?", "fields": [{"id": "a5", "type": "math", "kind": "number", "label": "Jawapan akhir", "answer": 204, "max": 2, "topic": "Wang", "model": "Diskaun = 15/100 × RM240 = RM36 (1). Harga selepas diskaun = RM240 − RM36 = RM204 (1).", "displayUnit": "RM", "units": ["RM", "ringgit"]}], "topic": "Wang"}, {"id": "a6", "section": "A", "title": "Soalan 6", "intro": "Aina menyimpan RM2 000. Kadar faedah mudah yang diberikan dalam soalan ini ialah 3% setahun. Hitung faedah untuk satu tahun.", "fields": [{"id": "a6", "type": "math", "kind": "number", "label": "Jawapan akhir", "answer": 60, "max": 2, "topic": "Wang", "model": "Faedah mudah setahun = 3/100 × RM2 000 (1) = RM60 (1). Kadar ini data rekaan untuk latihan.", "displayUnit": "RM", "units": ["RM", "ringgit"]}], "topic": "Wang"}, {"id": "a7", "section": "A", "title": "Soalan 7", "intro": "Bandar P menggunakan GMT+8 dan Bandar Q menggunakan GMT+2. Apabila waktu di P ialah 18:15, nyatakan waktu di Q pada hari yang sama dalam format 24 jam.", "fields": [{"id": "a7", "type": "math", "kind": "time", "label": "Jawapan akhir", "answer": "12:15", "max": 2, "topic": "Masa dan waktu", "model": "Perbezaan masa = 8 − 2 = 6 jam (1). Q lewat 6 jam: 18:15 − 6 jam = 12:15 (1).", "displayUnit": "HH:MM (24 jam)"}], "topic": "Masa dan waktu"}, {"id": "a8", "section": "A", "title": "Soalan 8", "intro": "Bandar P menggunakan GMT+8 dan Bandar R menggunakan GMT+10. Waktu di P ialah 23:30 pada 12 November 2026. Nyatakan waktu dan tarikh di R.", "fields": [{"id": "a8a", "type": "math", "kind": "time", "label": "(a) Waktu di R dalam format 24 jam.", "answer": "01:30", "max": 1, "topic": "Masa dan waktu", "model": "R awal 2 jam. 23:30 + 2 jam = 01:30 pada hari berikutnya (1).", "displayUnit": "HH:MM (24 jam)"}, {"id": "a8b", "type": "math", "kind": "word", "label": "(b) Tarikh di R.", "answer": "13 November 2026", "max": 1, "topic": "Masa dan waktu", "model": "13 November 2026 (1). Terima 13/11/2026 atau 13 Nov 2026.", "accepted": ["13 November 2026", "13 Nov 2026", "13/11/2026", "13-11-2026"], "displayUnit": "hh/bb/tttt"}], "topic": "Masa dan waktu"}, {"id": "a9", "section": "A", "title": "Soalan 9", "intro": "Wayar seragam sepanjang 2.5 m mempunyai jisim 0.6 kg. Hitung jisim wayar yang sama jenis sepanjang 7.5 m.", "fields": [{"id": "a9", "type": "math", "kind": "number", "label": "Jawapan akhir", "answer": 1.8, "max": 2, "topic": "Ukuran dan sukatan", "model": "7.5 ÷ 2.5 = 3 (1). Jisim = 3 × 0.6 kg = 1.8 kg (1).", "displayUnit": "kg", "units": ["kg", "kilogram"]}], "topic": "Ukuran dan sukatan"}, {"id": "a10", "section": "A", "title": "Soalan 10", "intro": "Rajah menunjukkan bulatan berpusat O. Jejari OB ialah 4.5 cm. A, O dan B berada pada satu garis lurus. Berapakah panjang diameter AB?", "fields": [{"id": "a10", "type": "math", "kind": "number", "label": "Jawapan akhir", "answer": 9, "max": 2, "topic": "Ruang", "model": "Diameter = 2 × jejari (1) = 2 × 4.5 cm = 9 cm (1).", "displayUnit": "cm", "units": ["cm", "sentimeter"]}], "topic": "Ruang", "image": "assets/math-circle.svg", "imageAlt": "Bulatan berpusat O, dengan A dan B di hujung diameter. Jejari OB 4.5 cm. Rajah tidak mengikut skala."}, {"id": "a11", "section": "A", "title": "Soalan 11", "intro": "Sebuah heksagon sekata mempunyai jumlah sudut pedalaman 720°. Hitung satu sudut pedalamannya.", "fields": [{"id": "a11", "type": "math", "kind": "number", "label": "Jawapan akhir", "answer": 120, "max": 2, "topic": "Ruang", "model": "Heksagon sekata mempunyai 6 sudut yang sama besar (1). Satu sudut = 720° ÷ 6 = 120° (1).", "displayUnit": "darjah (°)", "units": ["°", "darjah"]}], "topic": "Ruang"}, {"id": "a12", "section": "A", "title": "Soalan 12", "intro": "Pada peta grid, P berada di (2, 3) dan Q di (7, 3). Skala mengufuk ialah 1 unit mewakili 2 km. Hitung jarak sebenar antara P dengan Q.", "fields": [{"id": "a12", "type": "math", "kind": "number", "label": "Jawapan akhir", "answer": 10, "max": 2, "topic": "Koordinat, nisbah dan kadaran", "model": "Beza koordinat mengufuk = 7 − 2 = 5 unit (1). Jarak = 5 × 2 km = 10 km (1).", "displayUnit": "km", "units": ["km", "kilometer"]}], "topic": "Koordinat, nisbah dan kadaran", "image": "assets/math-grid.svg", "imageAlt": "Grid sukuan pertama: P (2,3), Q (7,3). Jarak antara kedua-duanya mengufuk; 1 unit mewakili 2 km."}, {"id": "a13", "section": "A", "title": "Soalan 13", "intro": "Carta pai menunjukkan aktiviti pilihan 40 orang murid. Sektor Sukan ialah 180°, Seni 90° dan Muzik 90°. Berapakah bilangan murid yang memilih Seni?", "fields": [{"id": "a13", "type": "math", "kind": "number", "label": "Jawapan akhir", "answer": 10, "max": 2, "topic": "Pengurusan data dan kebolehjadian", "model": "Bahagian Seni = 90°/360° = 1/4 (1). Bilangan murid = 1/4 × 40 = 10 orang (1).", "displayUnit": "orang", "units": ["orang", "murid"]}], "topic": "Pengurusan data dan kebolehjadian", "image": "assets/math-pie.svg", "imageAlt": "Carta pai: Sukan separuh bulatan (180°), Seni suku bulatan (90°), Muzik suku bulatan (90°). Jumlah 40 murid."}, {"id": "b1", "section": "B", "title": "1. Jelajah ilmu dan jualan cenderamata", "intro": "Jawab semua bahagian. Maklumat setiap bahagian adalah berasingan. Tunjukkan jalan kerja di ruang yang disediakan.", "fields": [{"id": "b1a", "type": "math", "kind": "number", "label": "(a) Pusat Sains menerima 1.2 juta pengunjung pada separuh pertama tahun dan 3/4 juta pada separuh kedua. Hitung jumlah pengunjung dalam nombor bulat.", "answer": 1950000, "max": 2, "topic": "Nombor bulat dan operasi asas", "model": "3/4 juta = 0.75 juta; jumlah = 1.2 + 0.75 = 1.95 juta (1) = 1 950 000 pengunjung (1).", "displayUnit": "orang", "units": ["orang", "pengunjung"]}, {"id": "b1b", "type": "math", "kind": "number", "label": "(b) Sebuah muzium menerima 0.8 juta pengunjung pada tahun lalu. Tahun ini, bilangannya ialah 125% daripada tahun lalu. Hitung bilangan pengunjung tahun ini dalam nombor bulat.", "answer": 1000000, "max": 3, "topic": "Pecahan, perpuluhan dan peratus", "model": "125% = 1.25 (1). 1.25 × 0.8 juta = 1 juta (1). Jawapan = 1 000 000 pengunjung (1).", "displayUnit": "orang", "units": ["orang", "pengunjung"]}, {"id": "b1c", "type": "math", "kind": "number", "label": "(c) Kos sebuah cenderamata ialah RM12. Harga tandanya RM15.90. Selepas rebat RM0.90 diberikan, berapakah untung bagi satu cenderamata?", "answer": 3, "max": 2, "topic": "Wang", "model": "Harga jual sebenar = RM15.90 − RM0.90 = RM15 (1). Untung = RM15 − RM12 = RM3 (1).", "displayUnit": "RM", "units": ["RM", "ringgit"]}, {"id": "b1d", "type": "math", "kind": "time", "label": "(d) Sebuah penerbangan bertolak dari Bandar P (GMT+8) pada 09:00. Penerbangan mengambil masa 2 jam ke Bandar S (GMT+7). Nyatakan waktu ketibaan di S dalam format 24 jam.", "answer": "10:00", "max": 2, "topic": "Masa dan waktu", "model": "Tiba pada 11:00 mengikut waktu P (1). S lewat 1 jam, maka waktu tempatan ketibaan ialah 10:00 (1).", "displayUnit": "HH:MM (24 jam)"}, {"id": "b1e", "type": "math", "kind": "number", "label": "(e) Nisbah bilangan pengunjung dewasa kepada kanak-kanak ialah 2 : 3. Jumlah pengunjung ialah 250 orang. Hitung bilangan kanak-kanak.", "answer": 150, "max": 3, "topic": "Koordinat, nisbah dan kadaran", "model": "Jumlah bahagian = 2 + 3 = 5 (1). Satu bahagian = 250 ÷ 5 = 50 (1). Kanak-kanak = 3 × 50 = 150 orang (1).", "displayUnit": "orang", "units": ["orang", "kanak-kanak"]}]}, {"id": "b2", "section": "B", "title": "2. Karnival Matematik", "intro": "Jawab semua bahagian. Setiap situasi diberi secara berasingan. Data dan kadar dalam soalan ialah rekaan untuk latihan.", "fields": [{"id": "b2ai", "type": "math", "kind": "number", "label": "(a)(i) Sebanyak 1.5 L minuman mempunyai jisim 1.2 kg. Pada kadar campuran yang sama, hitung jisim 7.5 L minuman itu.", "answer": 6, "max": 2, "topic": "Ukuran dan sukatan", "model": "Faktor gandaan = 7.5 ÷ 1.5 = 5 (1). Jisim = 5 × 1.2 kg = 6 kg (1).", "displayUnit": "kg", "units": ["kg", "kilogram"]}, {"id": "b2aii", "type": "math", "kind": "number", "label": "(a)(ii) Semua 7.5 L minuman itu diisi ke dalam botol 250 mL. Berapakah botol penuh yang diperoleh?", "answer": 30, "max": 2, "topic": "Ukuran dan sukatan", "model": "7.5 L = 7 500 mL (1). Bilangan botol = 7 500 ÷ 250 = 30 botol (1).", "displayUnit": "botol", "units": ["botol"]}, {"id": "b2b", "type": "math", "kind": "number", "label": "(b) Hiasan berbentuk pentagon sekata mempunyai jumlah sudut pedalaman 540°. Hitung satu sudut pedalamannya.", "answer": 108, "max": 2, "topic": "Ruang", "model": "Pentagon sekata mempunyai 5 sudut sama besar (1). Satu sudut = 540° ÷ 5 = 108° (1).", "displayUnit": "darjah (°)", "units": ["°", "darjah"]}, {"id": "b2c", "type": "math", "kind": "number", "label": "(c) Lima tiket berharga RM20. Pada kadar yang sama, berapakah harga lapan tiket?", "answer": 32, "max": 2, "topic": "Koordinat, nisbah dan kadaran", "model": "Harga satu tiket = RM20 ÷ 5 = RM4 (1). Harga 8 tiket = 8 × RM4 = RM32 (1).", "displayUnit": "RM", "units": ["RM", "ringgit"]}, {"id": "b2di", "type": "math", "kind": "number", "label": "(d)(i) Daripada 60 pengunjung, 15 memilih gerai robotik. Hitung sudut sektor Robotik dalam carta pai bagi semua pengunjung.", "answer": 90, "max": 2, "topic": "Pengurusan data dan kebolehjadian", "model": "Bahagian Robotik = 15/60 = 1/4 (1). Sudut sektor = 1/4 × 360° = 90° (1).", "displayUnit": "darjah (°)", "units": ["°", "darjah"]}, {"id": "b2dii", "type": "math", "kind": "word", "label": "(d)(ii) Sebuah kotak hanya mengandungi 5 bola merah dan 3 bola biru. Satu bola diambil tanpa melihat. Nyatakan kebolehjadian mendapat bola hijau. Gunakan istilah yang sesuai.", "answer": "Mustahil", "max": 1, "topic": "Pengurusan data dan kebolehjadian", "model": "Mustahil (1). Tiada bola hijau dalam kotak.", "accepted": ["mustahil"]}, {"id": "b2diii", "type": "text", "label": "(d)(iii) Berikan sebab bagi jawapan (d)(ii).", "max": 1, "topic": "Pengurusan data dan kebolehjadian", "model": "Tiada bola hijau dalam kotak / kotak hanya mengandungi bola merah dan biru (1). Terima alasan setara yang betul.", "rules": [[["tiada", "tidak ada", "tidak mempunyai", "tidak mengandungi"], ["hijau"]]], "concepts": [["tiada bola hijau"]]}]}];
